/*!
 * VibeHive in-app notifications.
 *
 * Ported from ta-society-helpdesk's header bell + dropdown pattern, but
 * adapted to VibeHive's client-only static-SPA model: notifications are
 * generated by domain writers (event publish, contribution verify,
 * receipt mint) into localStorage and rendered from there. There is no
 * poller — a cross-tab `storage` listener keeps the bell live across
 * open tabs, and every state-changing helper here re-renders in-place.
 *
 * Public API:
 *   emit({audience, userId, userEmail, role, kind, title, body, link})
 *   listMine(limit?)              → newest-first slice for the current user
 *   unreadCount()                 → number for badge
 *   markRead(id)                  → mark one item read
 *   markAllRead()                 → mark every visible item read
 *   mountBell(container)          → wire the header bell button + dropdown
 *
 * Audiences:
 *   'all'  — visible to any signed-in user (event published, banner…).
 *   'role' — visible to a specific role (e.g. 'committee').
 *   'user' — visible to one user, matched by id OR case-insensitive email.
 */
'use strict';
import { local, state } from './store.js';

const NOTIF_KEY = 'notifications';
const MAX_STORED = 200;
const LIST_LIMIT = 20;

const refs = {
  bell: null,
  count: null,
  wrap: null,
  drop: null,
};

function all() { return local.get(NOTIF_KEY, []); }
function persist(list) { local.set(NOTIF_KEY, list.slice(-MAX_STORED)); }

function currentUser() { return state.currentUser(); }

function forMe(n) {
  const u = currentUser();
  if (!u) return false;
  if (n.audience === 'all') return true;
  if (n.audience === 'role') return n.role === u.role;
  if (n.audience === 'user') {
    if (n.userId && n.userId === u.id) return true;
    if (n.userEmail && u.email && String(n.userEmail).toLowerCase() === String(u.email).toLowerCase()) return true;
    return false;
  }
  return false;
}

function esc(s) {
  return String(s).replace(/[&<>"']/g, c => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

function relTime(iso) {
  try {
    const t = new Date(iso).getTime();
    const s = Math.max(1, Math.round((Date.now() - t) / 1000));
    if (s < 60)    return `${s}s ago`;
    if (s < 3600)  return `${Math.round(s / 60)}m ago`;
    if (s < 86400) return `${Math.round(s / 3600)}h ago`;
    return `${Math.round(s / 86400)}d ago`;
  } catch (_e) { return ''; }
}

export function emit({ audience = 'all', userId, userEmail, role, kind = 'info', title, body = '', link = '' }) {
  if (!title) return null;
  const id = 'ntf-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
  const row = {
    id,
    audience,
    userId: userId || null,
    userEmail: userEmail ? String(userEmail).toLowerCase() : null,
    role: role || null,
    kind,
    title: String(title).slice(0, 200),
    body: String(body || '').slice(0, 400),
    link: String(link || ''),
    createdAt: new Date().toISOString(),
    readAt: null,
  };
  const list = all();
  list.push(row);
  persist(list);
  render();
  return row;
}

export function listMine(limit = LIST_LIMIT) {
  return all().filter(forMe).slice(-limit).reverse();
}

export function unreadCount() {
  return all().reduce((n, x) => n + (forMe(x) && !x.readAt ? 1 : 0), 0);
}

export function markRead(id) {
  const list = all();
  const i = list.findIndex(n => n.id === id);
  if (i < 0 || list[i].readAt) return;
  list[i].readAt = new Date().toISOString();
  persist(list);
  render();
}

export function markAllRead() {
  const list = all();
  const now = new Date().toISOString();
  let changed = false;
  for (const n of list) {
    if (forMe(n) && !n.readAt) { n.readAt = now; changed = true; }
  }
  if (changed) persist(list);
  render();
}

function ensureDrop() {
  if (refs.drop) return refs.drop;
  const d = document.createElement('div');
  d.className = 'tvh-notify-drop';
  d.setAttribute('role', 'dialog');
  d.setAttribute('aria-label', 'Notifications');
  d.innerHTML = `
    <div class="tvh-notify-head">
      <span>Notifications</span>
      <button type="button" data-tvh-mark-all>Mark all read</button>
    </div>
    <div class="tvh-notify-list" data-tvh-list></div>`;
  document.body.appendChild(d);
  d.querySelector('[data-tvh-mark-all]').addEventListener('click', (ev) => {
    ev.preventDefault();
    markAllRead();
    renderList();
  });
  refs.drop = d;
  return d;
}

function position() {
  if (!refs.drop || !refs.bell) return;
  const r = refs.bell.getBoundingClientRect();
  const width = Math.min(360, window.innerWidth - 24);
  refs.drop.style.top   = (r.bottom + 8) + 'px';
  let left = r.right - width;
  if (left < 12) left = 12;
  refs.drop.style.left  = left + 'px';
  refs.drop.style.width = width + 'px';
}

function open() {
  const d = ensureDrop();
  position();
  d.classList.add('is-open');
  refs.bell.setAttribute('aria-expanded', 'true');
  renderList();
}
function close() {
  if (!refs.drop) return;
  refs.drop.classList.remove('is-open');
  if (refs.bell) refs.bell.setAttribute('aria-expanded', 'false');
}
function toggle() {
  if (!refs.drop || !refs.drop.classList.contains('is-open')) open();
  else close();
}

function renderList() {
  const d = ensureDrop();
  const list = d.querySelector('[data-tvh-list]');
  const items = listMine(LIST_LIMIT);
  if (!items.length) {
    list.innerHTML = `<div class="tvh-notify-empty">You're all caught up. 🌿</div>`;
    return;
  }
  list.innerHTML = items.map(n => `
    <a class="tvh-notify-item${n.readAt ? '' : ' is-unread'}"
       href="${esc(n.link || '#')}"
       data-nid="${esc(n.id)}"
       data-kind="${esc(n.kind || 'info')}">
      <div class="tvh-notify-item-t">${esc(n.title)}</div>
      ${n.body ? `<div class="tvh-notify-item-b">${esc(n.body)}</div>` : ''}
      <div class="tvh-notify-item-m">${esc(relTime(n.createdAt))}</div>
    </a>`).join('');
  list.querySelectorAll('.tvh-notify-item').forEach(a => {
    a.addEventListener('click', (ev) => {
      const id   = a.getAttribute('data-nid');
      const href = a.getAttribute('href') || '';
      markRead(id);
      if (!href || href === '#') { ev.preventDefault(); close(); return; }
      close();
    });
  });
}

function render() {
  if (!refs.bell || !refs.count || !refs.wrap) return;
  const u = currentUser();
  if (!u) { refs.wrap.hidden = true; return; }
  refs.wrap.hidden = false;
  const n = unreadCount();
  if (n > 0) {
    refs.count.textContent = n > 99 ? '99+' : String(n);
    refs.count.hidden = false;
  } else {
    refs.count.textContent = '0';
    refs.count.hidden = true;
  }
  if (refs.drop && refs.drop.classList.contains('is-open')) renderList();
}

export function mountBell(container) {
  if (!container) return;
  /* Idempotent: repeated topbar re-renders would otherwise stack bells.
   * Reuse if the current bell is still attached; otherwise recreate. */
  if (refs.bell && container.contains(refs.bell)) { render(); return; }

  const wrap = document.createElement('span');
  wrap.className = 'tvh-bell-wrap';
  wrap.innerHTML = `
    <button type="button" class="tvh-bell" data-tvh-bell aria-label="Notifications" aria-haspopup="true" aria-expanded="false">
      <svg class="tvh-bell-ico" viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
        <path fill="currentColor" d="M12 22a2.5 2.5 0 0 0 2.45-2H9.55A2.5 2.5 0 0 0 12 22Zm7-6v-5a7 7 0 0 0-5.5-6.83V3.5a1.5 1.5 0 0 0-3 0v.67A7 7 0 0 0 5 11v5l-2 2v1h18v-1l-2-2Z"/>
      </svg>
      <span class="tvh-bell-badge" data-tvh-count hidden>0</span>
    </button>`;
  container.appendChild(wrap);
  refs.wrap  = wrap;
  refs.bell  = wrap.querySelector('[data-tvh-bell]');
  refs.count = wrap.querySelector('[data-tvh-count]');

  refs.bell.addEventListener('click', (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    toggle();
  });
  render();
}

/* Global outside-click + resize + cross-tab wiring. Attached once. */
if (typeof document !== 'undefined' && !document.__tvhNotifyWired) {
  document.__tvhNotifyWired = true;
  document.addEventListener('click', (ev) => {
    if (!refs.drop || !refs.drop.classList.contains('is-open')) return;
    if (refs.bell && refs.bell.contains(ev.target)) return;
    if (refs.drop.contains(ev.target)) return;
    close();
  });
  document.addEventListener('keydown', (ev) => {
    if (ev.key === 'Escape' && refs.drop && refs.drop.classList.contains('is-open')) close();
  });
  window.addEventListener('resize', () => {
    if (refs.drop && refs.drop.classList.contains('is-open')) position();
  });
  window.addEventListener('storage', (e) => {
    if (!e.key) return;
    if (e.key.endsWith(':' + NOTIF_KEY) || e.key.endsWith(':session')) render();
  });
}
